import numpy as np

def compute_probabilities(
    pheromone: np.ndarray,
    heuristic: np.ndarray,
    iteration: int,
    n_iterations: int
) -> np.ndarray:
    alpha = 1.0 + (0.5 * (iteration / n_iterations))  # increase influence over time
    beta = 1.0 + (0.5 * (1 - iteration / n_iterations))  # decrease influence over time
    return np.power(pheromone, alpha) * np.power(heuristic, beta)
